-- =====================================================================
-- Waterdrop — empty can tracking.
-- At each delivery the supplier (or delivery staff) records how many
-- empty cans were taken back for refilling. Every customer gets a running
-- "cans with customer" balance: full cans given − empty cans taken back
-- (+ a supplier correction for cans they held before using Waterdrop).
-- GENERATED by scripts/gen-migration-14.py (do not edit by hand).
-- =====================================================================

alter table public.deliveries
  add column empty_cans_collected integer not null default 0 check (empty_cans_collected between 0 and 1000);

alter table public.customers
  add column cans_out_correction integer not null default 0 check (cans_out_correction between -100000 and 100000);

-- Supplier cans currently at the customer. Internal (no access check).
create or replace function public.cans_out(p_customer_id uuid) returns integer
language sql stable security definer set search_path = public as $$
  select (select cans_out_correction from public.customers where id = p_customer_id)
       + coalesce((select sum(case d.status
                               when 'confirmed' then coalesce(d.confirmed_quantity, 0) + d.adjusted_quantity
                               when 'awaiting_confirmation' then d.actual_quantity
                               else 0 end
                             - case when d.status = 'cancelled' then 0 else d.empty_cans_collected end)
                   from public.deliveries d where d.customer_id = p_customer_id), 0)::integer;
$$;

-- Deliveries before this feature never recorded empty cans, so start every
-- existing customer at 0 cans out; the supplier sets the real count once
-- with "Correct count".
update public.customers set cans_out_correction = -public.cans_out(id)
where public.cans_out(id) <> 0;

-- record_delivery gains p_empty_cans (older apps omit it: 0).
drop function public.record_delivery(uuid, integer, integer, date, uuid, text);
create or replace function public.record_delivery(
  p_customer_id uuid,
  p_expected_quantity integer,
  p_actual_quantity integer,
  p_delivery_date date default null,
  p_order_id uuid default null,
  p_notes text default null,
  p_empty_cans integer default 0
) returns public.deliveries
language plpgsql security definer set search_path = public as $$
declare
  v_sid uuid := public.require_supplier_member();
  c public.customers;
  o public.orders;
  d public.deliveries;
  v_date date;
begin
  select * into c from public.customers where id = p_customer_id and supplier_id = v_sid;
  if c.id is null then
    raise exception 'Customer not found' using errcode = 'P0002';
  end if;
  if p_expected_quantity is null or p_actual_quantity is null
     or p_expected_quantity < 0 or p_actual_quantity < 0
     or p_expected_quantity > 1000 or p_actual_quantity > 1000 then
    raise exception 'Quantities must be between 0 and 1000' using errcode = '22023';
  end if;
  if coalesce(p_empty_cans, 0) not between 0 and 1000 then
    raise exception 'Empty cans must be between 0 and 1000' using errcode = '22023';
  end if;
  v_date := coalesce(p_delivery_date, public.customer_local_date(c.id));
  if v_date > public.customer_local_date(c.id) + 1 then
    raise exception 'Delivery date cannot be in the future' using errcode = '22023';
  end if;

  if p_order_id is not null then
    select * into o from public.orders where id = p_order_id for update;
    if o.id is null or o.customer_id <> c.id or o.supplier_id <> v_sid then
      raise exception 'Order does not belong to this customer' using errcode = '22023';
    end if;
    if o.status not in ('accepted', 'preparing', 'out_for_delivery') then
      raise exception 'Order must be accepted before it can be delivered (status: %)', o.status using errcode = '22023';
    end if;
    if exists (select 1 from public.deliveries where order_id = o.id and status <> 'cancelled') then
      raise exception 'A delivery is already recorded for this order' using errcode = '23505';
    end if;
  end if;

  insert into public.deliveries (supplier_id, customer_id, order_id, expected_quantity, actual_quantity, unit_price,
                                 delivery_date, notes, created_by, empty_cans_collected)
  values (v_sid, c.id, p_order_id, p_expected_quantity, p_actual_quantity, public.effective_can_price(c.id),
          v_date, nullif(trim(coalesce(p_notes, '')), ''), auth.uid(), coalesce(p_empty_cans, 0))
  returning * into d;

  if o.id is not null then
    insert into public.order_status_history (order_id, from_status, to_status, changed_by, reason)
    values (o.id, o.status, 'delivered', auth.uid(), 'Delivery recorded; awaiting customer confirmation');
    update public.orders set status = 'delivered' where id = o.id;
  end if;

  perform public.write_audit('delivery.recorded', 'delivery', d.id, v_sid,
    jsonb_build_object('expected', p_expected_quantity, 'actual', p_actual_quantity, 'empty_cans', coalesce(p_empty_cans, 0)));

  if c.user_id is null then
    -- Offline customer: supplier confirms on their behalf (flagged for reporting).
    d := public.apply_delivery_confirmation(d.id, p_actual_quantity, 'Confirmed by supplier (offline customer)', true);
  else
    perform public.notify_customer(c.id, 'all', 'delivery_confirmation_required', 'warning',
      'Please confirm your water delivery',
      format('Your supplier recorded %s can%s delivered on %s. Confirm how many you actually received.',
             p_actual_quantity, case when p_actual_quantity = 1 then '' else 's' end, to_char(v_date, 'DD Mon')),
      '/app/deliveries', jsonb_build_object('delivery_id', d.id), 'confirm_delivery:' || d.id);
  end if;
  return d;
end $$;

drop function public.list_supplier_customers();
create or replace function public.list_supplier_customers()
returns table (
  id uuid, customer_name text, phone text, address text, status public.customer_status, has_app boolean,
  current_stock integer, stock_confirmed boolean, level text, predicted_empty_date date,
  daily_consumption integer, can_price numeric, balance numeric, created_at timestamptz,
  household_type text, members_count integer, blocked boolean,
  account_name text, account_type text, branch_name text, bill_to_customer_id uuid, cans_out integer
)
language sql stable security definer set search_path = public as $$
  select c.id, c.customer_name, c.phone, c.address, c.status, c.user_id is not null,
         coalesce(s.current_stock, 0), coalesce(s.has_opening_stock, false),
         case when not coalesce(s.has_opening_stock, false) then 'unknown'
              else case public.stock_level_for(s.current_stock, c.low_stock_threshold, c.critical_threshold)
                     when 'critical' then 'critical' when 'low' then 'low' else 'ok' end end,
         s.predicted_empty_date, c.daily_consumption, public.effective_can_price(c.id),
         case when c.bill_to_customer_id is null then public.customer_balance(c.id) end, c.created_at,
         c.household_type, c.members_count, c.blocked_at is not null,
         a.name, a.account_type::text, c.branch_name, c.bill_to_customer_id, public.cans_out(c.id)
  from public.customers c left join public.customer_stock s on s.customer_id = c.id
  left join public.customer_accounts a on a.id = c.account_id
  where c.supplier_id = public.my_supplier_id()
  order by c.customer_name;
$$;

-- For the customer app (and the supplier): cans of the supplier at this branch.
create or replace function public.cans_with_customer(p_customer_id uuid) returns integer
language plpgsql stable security definer set search_path = public as $$
declare v_sid uuid;
begin
  perform public.require_auth();
  select supplier_id into v_sid from public.customers where id = p_customer_id;
  if v_sid is null then
    raise exception 'Customer not found' using errcode = 'P0002';
  end if;
  if not coalesce(p_customer_id in (select public.my_customer_ids()) or v_sid = public.my_supplier_id() or public.is_admin(), false) then
    raise exception 'Not allowed for this customer' using errcode = '42501';
  end if;
  return public.cans_out(p_customer_id);
end $$;

-- Fix the empty-can count of a recorded delivery (any co-worker; works after confirmation too).
create or replace function public.set_delivery_empty_cans(p_delivery_id uuid, p_empty_cans integer)
returns public.deliveries
language plpgsql security definer set search_path = public as $$
declare
  v_sid uuid := public.require_supplier_member();
  d public.deliveries;
  v_old integer;
begin
  select * into d from public.deliveries where id = p_delivery_id and supplier_id = v_sid for update;
  if d.id is null then
    raise exception 'Delivery not found' using errcode = 'P0002';
  end if;
  if d.status = 'cancelled' then
    raise exception 'This delivery was cancelled' using errcode = '22023';
  end if;
  if p_empty_cans is null or p_empty_cans not between 0 and 1000 then
    raise exception 'Empty cans must be between 0 and 1000' using errcode = '22023';
  end if;
  v_old := d.empty_cans_collected;
  update public.deliveries set empty_cans_collected = p_empty_cans where id = d.id returning * into d;
  perform public.write_audit('delivery.empty_cans_changed', 'delivery', d.id, v_sid, jsonb_build_object('from', v_old, 'to', p_empty_cans));
  return d;
end $$;

-- Set how many cans the customer has right now (e.g. cans given before Waterdrop). Owner / manager.
create or replace function public.set_cans_with_customer(p_customer_id uuid, p_count integer, p_reason text default null)
returns integer
language plpgsql security definer set search_path = public as $$
declare
  v_sid uuid := public.require_active_supplier();
  v_now integer;
begin
  if not exists (select 1 from public.customers where id = p_customer_id and supplier_id = v_sid) then
    raise exception 'Customer not found' using errcode = 'P0002';
  end if;
  if p_count is null or p_count not between 0 and 10000 then
    raise exception 'Cans must be between 0 and 10000' using errcode = '22023';
  end if;
  v_now := public.cans_out(p_customer_id);
  update public.customers set cans_out_correction = cans_out_correction + (p_count - v_now) where id = p_customer_id;
  perform public.write_audit('customer.cans_out_set', 'customer', p_customer_id, v_sid,
    jsonb_build_object('from', v_now, 'to', p_count, 'reason', nullif(trim(coalesce(p_reason, '')), '')));
  return p_count;
end $$;

-- Daily can movement for the supplier: full cans given, empty cans taken back, per co-worker.
create or replace function public.supplier_can_report(p_date date default null) returns jsonb
language plpgsql stable security definer set search_path = public as $$
declare
  v_sid uuid := public.require_supplier_member();
  v_date date := coalesce(p_date, (now() at time zone 'Asia/Kolkata')::date);
begin
  return jsonb_build_object(
    'date', v_date,
    'deliveries', (select count(*) from public.deliveries where supplier_id = v_sid and delivery_date = v_date and status <> 'cancelled'),
    'full_cans', (select coalesce(sum(actual_quantity), 0) from public.deliveries
                  where supplier_id = v_sid and delivery_date = v_date and status <> 'cancelled'),
    'empty_cans', (select coalesce(sum(empty_cans_collected), 0) from public.deliveries
                   where supplier_id = v_sid and delivery_date = v_date and status <> 'cancelled'),
    'cans_with_customers', (select coalesce(sum(greatest(public.cans_out(id), 0)), 0) from public.customers where supplier_id = v_sid),
    'by_person', coalesce((select jsonb_agg(x order by x->>'name') from (
        select jsonb_build_object(
                 'name', coalesce(st.staff_name, case when d.created_by = s.owner_id then s.owner_name end, p.full_name, 'Unknown'),
                 'deliveries', count(*), 'full_cans', sum(d.actual_quantity), 'empty_cans', sum(d.empty_cans_collected)) as x
        from public.deliveries d
        join public.suppliers s on s.id = d.supplier_id
        left join public.supplier_staff st on st.supplier_id = d.supplier_id and st.user_id = d.created_by
        left join public.profiles p on p.id = d.created_by
        where d.supplier_id = v_sid and d.delivery_date = v_date and d.status <> 'cancelled'
        group by st.staff_name, s.owner_id, s.owner_name, p.full_name, d.created_by) t), '[]'::jsonb)
  );
end $$;

do $$
declare f text;
begin
  foreach f in array array[
    'public.record_delivery(uuid, integer, integer, date, uuid, text, integer)',
    'public.list_supplier_customers()',
    'public.cans_with_customer(uuid)',
    'public.set_delivery_empty_cans(uuid, integer)',
    'public.set_cans_with_customer(uuid, integer, text)',
    'public.supplier_can_report(date)'
  ] loop
    execute format('revoke execute on function %s from public, anon', f);
    execute format('grant execute on function %s to authenticated, service_role', f);
  end loop;
  execute 'revoke execute on function public.cans_out(uuid) from public, anon, authenticated';
  execute 'grant execute on function public.cans_out(uuid) to service_role';
end $$;
